session_story_bible:
Treat these as immutable anchors for this session:
- Main character seed: {{Main_Character}}
- Character anchor (lock this identity): {{Character_Anchor}}
- Visual style (lock this style): {{Visual_Style}}
- Story setting (lock this place): {{Setting}}
- Target behavior: {{Target_Behavior}}

output_schema:
{
  "node_text": "String (Consequence + next situation. Max 2 sentences)",
  "visual_context": "String (MUST include locked visual_style + locked character_anchor + locked setting + current action/expression. Max 35 words)",
  "is_ending": Boolean,
  "choices": [
    { "choice_text": "Positive action", "behavior_type": "Positive" },
    { "choice_text": "Negative action", "behavior_type": "Negative" }
  ]
}
